<?php
require_once '../config.php';
require_staff();

$patientId=(int)($_GET['id']??0); $profileError=''; $patient=null; $appointments=[]; $visits=[]; $bills=[]; $reports=[];
function pv($r,$keys,$d='—'){foreach($keys as $k)if(isset($r[$k])&&trim((string)$r[$k])!=='')return $r[$k];return $d;}
function fd($v,$f='d M Y'){if(!$v)return '—';$t=strtotime($v);return $t?date($f,$t):$v;}
function sc($s){$s=preg_replace('/[^a-z0-9]+/','-',strtolower(trim((string)$s)));return trim($s,'-')?:'default';}
if($patientId>0){$st=$conn->prepare('SELECT * FROM patients WHERE id=? LIMIT 1');if($st){$st->bind_param('i',$patientId);$st->execute();$rs=$st->get_result();$patient=$rs?$rs->fetch_assoc():null;$st->close();}if(!$patient)$profileError='Patient record not found.';}else$profileError='Invalid patient ID.';
if($patient){
$q=[
'appointments'=>"SELECT id,service,date,time,status,patient_type,problem,problem_duration,problem_duration_unit,clinic,created_at FROM appointments WHERE patient_id=? ORDER BY date DESC,id DESC",
'visits'=>"SELECT id,opd_serial,visit_date,main_conditions,symptoms,duration_number,duration_unit,fee_required,fee_amount,fee_paid_date,status,diagnosis,prescription,lab_tests,consulted_at,created_by,created_at FROM visits WHERE patient_id=? ORDER BY visit_date DESC,id DESC",
'bills'=>"SELECT id,invoice_no,visit_id,bill_date,category,total_amount,discount,net_amount,payment_mode,notes,created_by,created_at FROM bills WHERE patient_id=? ORDER BY bill_date DESC,id DESC",
'reports'=>"SELECT id,visit_id,file_path,original_name,uploaded_at FROM reports WHERE patient_id=? ORDER BY uploaded_at DESC,id DESC"];
foreach($q as $key=>$sql){$st=$conn->prepare($sql);if($st){$st->bind_param('i',$patientId);$st->execute();$rs=$st->get_result();while($rs&&($row=$rs->fetch_assoc()))${$key}[]=$row;$st->close();}}
}
$name=$patient?pv($patient,['name','full_name','patient_name'],'Unknown Patient'):'';$code=$patient?pv($patient,['code'],''):'';$phone=$patient?pv($patient,['phone','mobile','phone_number','contact']):'—';$email=$patient?pv($patient,['email','email_address']):'—';$age=$patient?pv($patient,['age']):'—';$gender=$patient?pv($patient,['gender','sex']):'—';$address=$patient?pv($patient,['address']):'—';$area=$patient?pv($patient,['area','locality']):'—';$district=$patient?pv($patient,['district','city']):'—';$conditions=$patient?pv($patient,['chronic_conditions','conditions'],'No conditions recorded.'):' ';$registered=$patient?pv($patient,['created_at']):'';
$completed=0;$total=0;foreach($visits as $v)if(strcasecmp((string)$v['status'],'Completed')===0)$completed++;foreach($bills as $b)$total+=(float)($b['net_amount']??0);
?>
