space-between;align-items:flex-start;gap:15px;margin-bottom:17px}.section-head h2{margin:0 0 4px;color:#102a43;font-size:20px}.section-head p{margin:0;color:#64748b}.badge-count{background:#eff6ff;color:#1d4ed8;padding:7px 11px;border-radius:999px;font-weight:900;white-space:nowrap}.timeline{display:grid;gap:13px}.timeline-item{border:1px solid #e2e8f0;border-radius:14px;background:#f8fafc;padding:17px}.timeline-top{display:flex;justify-content:space-between;gap:15px;align-items:flex-start}.timeline-top h3{margin:0 0 4px;color:#17365d;font-size:16px}.muted{color:#64748b;font-size:12px}.meta-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:13px}.meta{background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:10px}.meta span,.long-box label{display:block;color:#94a3b8;text-transform:uppercase;font-size:9px;font-weight:900;margin-bottom:4px}.meta strong{color:#334155;font-size:13px;white-space:pre-wrap}.long-box{margin-top:12px;background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:12px}.long-box div{color:#334155;line-height:1.55;white-space:pre-wrap}.pill{display:inline-flex;padding:7px 10px;border-radius:999px;font-size:11px;font-weight:900}.pill.pending{background:#fff7ed;color:#c2410c}.pill.approved{background:#ecfdf5;color:#15803d}.pill.checked-in,.pill.waiting{background:#eef2ff;color:#4338ca}.pill.completed{background:#eff6ff;color:#1d4ed8}.pill.rejected{background:#fef2f2;color:#dc2626}.pill.default{background:#f1f5f9;color:#475569}.table-wrap{overflow:auto}.profile-table{width:100%;border-collapse:collapse;min-width:760px}.profile-table th,.profile-table td{padding:12px 11px;text-align:left;border-bottom:1px solid #e5e7eb}.profile-table th{font-size:11px;text-transform:uppercase;color:#64748b;background:#f8fafc}.profile-table td{color:#334155;font-size:13px}.money{font-weight:900;color:#0f766e}.empty{padding:32px;text-align:center;color:#64748b;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:13px}.report-link{font-weight:800;color:#2563eb;text-decoration:none}.alert-error{padding:15px;border-radius:12px;background:#fef2f2;color:#b91c1c;border:1px solid #fecaca;font-weight:700}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:1100px){.info-grid,.stats{grid-template-columns:repeat(2,1fr)}.meta-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.profile-header{flex-direction:column;align-items:flex-start}.code{margin-left:0}.info-grid,.stats,.meta-grid,.two-col{grid-template-columns:1fr}.info.full{grid-column:auto}.hero{padding:18px}.identity{align-items:flex-start}.profile-actions{width:100%}.pbtn{flex:1}}
