<?php if(!$patient): ?><div class="profile-header"><div><h1>Patient Profile</h1><p>Patient record viewer</p></div><a class="pbtn" href="patients.php">← Back to Patients</a></div><div class="alert-error"><?= e($profileError) ?></div><?php else: ?>
<div class="profile-header"><div><h1>Patient Profile</h1><p>Complete patient record, OPD history, appointments and billing.</p></div><div class="profile-actions"><a class="pbtn" href="patients.php">← Patients</a><?php if($appointments): ?><a class="pbtn primary" href="UpdateAppointment.php?id=<?= (int)$appointments[0]['id'] ?>&patient_id=<?= $patientId ?>">Manage Latest Appointment</a><?php endif; ?></div></div>
<section class="hero"><div class="identity"><div class="avatar"><?= e(strtoupper(substr(trim((string)$name),0,1))) ?></div><div><h2><?= e($name) ?></h2><p>Patient ID: <strong>AD-<?= e((string)$code) ?></strong> &nbsp;•&nbsp; <?= e($phone) ?></p></div><div class="code">AD-<?= e((string)$code) ?></div></div><div class="info-grid"><div class="info"><span>Mobile</span><strong><?= e($phone) ?></strong></div><div class="info"><span>Age</span><strong><?= e($age) ?></strong></div><div class="info"><span>Gender</span><strong><?= e($gender) ?></strong></div><div class="info"><span>District</span><strong><?= e($district) ?></strong></div><div class="info"><span>Address</span><strong><?= e($address) ?></strong></div><div class="info"><span>Area / Locality</span><strong><?= e($area) ?></strong></div><div class="info"><span>Email</span><strong><?= e($email) ?></strong></div><div class="info"><span>Registered</span><strong><?= e(fd($registered)) ?></strong></div><div class="info full"><span>Medical / Chronic Conditions</span><strong><?= e($conditions) ?></strong></div></div></section>
<section class="stats"><div class="stat"><small>Total Appointments</small><strong><?= count($appointments) ?></strong></div><div class="stat"><small>Total OPD Visits</small><strong><?= count($visits) ?></strong></div><div class="stat"><small>Completed Consultations</small><strong><?= $completed ?></strong></div><div class="stat"><small>Total Billed</small><strong>₹<?= number_format($total,2) ?></strong></div></section>
<section class="card-section"><div class="section-head"><div><h2>OPD / Consultation History</h2><p>Permanent clinical visit records for this patient.</p></div><span class="badge-count"><?= count($visits) ?> Visit(s)</span></div><?php if($visits): ?><div class="timeline"><?php foreach($visits as $v): ?><article class="timeline-item"><div class="timeline-top"><div><h3>OPD-<?= e((string)$v['opd_serial']) ?></h3><div class="muted"><?= e(fd($v['visit_date'])) ?><?php if($v['consulted_at']): ?> • Consulted <?= e(fd($v['consulted_at'],'d M Y, h:i A')) ?><?php endif; ?></div></div><span class="pill <?= e(sc($v['status'])) ?>"><?= e($v['status']?:'Pending') ?></span></div><div class="meta-grid"><div class="meta"><span>Chief Complaint</span><strong><?= e($v['main_conditions']?:'—') ?></strong></div><div class="meta"><span>Duration</span><strong><?= e(trim(($v['duration_number']??'').' '.($v['duration_unit']??''))?:'—') ?></strong></div><div class="meta"><span>Fee</span><strong>₹<?= number_format((float)($v['fee_amount']??0),2) ?></strong></div><div class="meta"><span>Created By</span><strong><?= e($v['created_by']?:'—') ?></strong></div></div><?php if($v['symptoms']): ?><div class="long-box"><label>Symptoms</label><div><?= e($v['symptoms']) ?></div></div><?php endif; ?><?php if($v['diagnosis']): ?><div class="long-box"><label>Diagnosis</label><div><?= e($v['diagnosis']) ?></div></div><?php endif; ?><?php if($v['prescription']): ?><div class="long-box"><label>Prescription</label><div><?= e($v['prescription']) ?></div></div><?php endif; ?><?php if($v['lab_tests']): ?><div class="long-box"><label>Lab / Radiology / Therapy Advice</label><div><?= e($v['lab_tests']) ?></div></div><?php endif; ?></article><?php endforeach; ?></div><?php else: ?><div class="empty">No OPD visits have been recorded for this patient.</div><?php endif; ?></section>
<section class="card-section"><div class="section-head"><div><h2>Appointment History</h2><p>Online and reception-created appointment records.</p></div><span class="badge-count"><?= count($appointments) ?> Appointment(s)</span></div><?php if($appointments): ?><div class="table-wrap"><table class="profile-table"><thead><tr><th>ID</th><th>Date / Time</th><th>Clinic</th><th>Problem</th><th>Service</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($appointments as $a): ?><tr><td>#<?= e((string)$a['id']) ?></td><td><strong><?= e(fd($a['date'])) ?></strong><br><span class="muted"><?= e($a['time']?:'—') ?></span></td><td><?= e($a['clinic']?:'—') ?></td><td><?= e($a['problem']?:'—') ?><br><span class="muted"><?= e(trim(($a['problem_duration']??'').' '.($a['problem_duration_unit']??''))) ?></span></td><td><?= e($a['service']?:'—') ?></td><td><span class="pill <?= e(sc($a['status'])) ?>"><?= e($a['status']?:'Pending') ?></span></td><td><a class="report-link" href="UpdateAppointment.php?id=<?= (int)$a['id'] ?>&patient_id=<?= $patientId ?>">Manage</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">No appointments found for this patient.</div><?php endif; ?></section>
<div class="two-col"><section class="card-section"><div class="section-head"><div><h2>Billing History</h2><p>Invoices and payments linked to this patient.</p></div><span class="badge-count"><?= count($bills) ?> Invoice(s)</span></div><?php if($bills): ?><div class="table-wrap"><table class="profile-table"><thead><tr><th>Invoice</th><th>Date</th><th>Category</th><th>Net Amount</th><th>Payment</th></tr></thead><tbody><?php foreach($bills as $b): ?><tr><td><strong><?= e($b['invoice_no']) ?></strong></td><td><?= e(fd($b['bill_date'])) ?></td><td><?= e($b['category']?:'—') ?></td><td class="money">₹<?= number_format((float)$b['net_amount'],2) ?></td><td><?= e($b['payment_mode']?:'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">No invoices found.</div><?php endif; ?></section>
<section class="card-section"><div class="section-head"><div><h2>Medical Reports</h2><p>Uploaded reports associated with this patient.</p></div><span class="badge-count"><?= count($reports) ?> Report(s)</span></div><?php if($reports): ?><div class="table-wrap"><table class="profile-table"><thead><tr><th>File</th><th>Visit</th><th>Uploaded</th><th>Open</th></tr></thead><tbody><?php foreach($reports as $r): ?><tr><td><strong><?= e($r['original_name']?:basename((string)$r['file_path'])) ?></strong></td><td><?= $r['visit_id']?'OPD visit #'.e((string)$r['visit_id']):'—' ?></td><td><?= e(fd($r['uploaded_at'],'d M Y, h:i A')) ?></td><td><?php if($r['file_path']): ?><a class="report-link" target="_blank" rel="noopener" href="<?= e($r['file_path']) ?>">Open</a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">No medical reports have been uploaded.</div><?php endif; ?></section></div>
<?php endif; ?></main></div></body></html>
